from Bio.Seq import Seq
from Bio.Data import CodonTable

def analyze_sequence(seq):
    """Analyze a DNA or RNA sequence and report on codon usage"""

    print(f"Sequence length: {len(seq)} bp")
    print(f"GC content: {seq.gc() * 100:.1f}%")
    print(f"Codon usage:")

    out = {}
    for codon in seq:
       if codon in out:
           out[codon] += 1
       else:
           out[codon] = 1

    for codon in out:
        print(f"{codon}: {out[codon]}")

