@app.route('/get_security_clearance', methods=['POST'])
def get_security_clearance():
    name = request.form['name']
    email = request.form['email']

    query = "SELECT clearance FROM users WHERE name = %s AND email = %s"
    cursor = db.cursor()
    cursor.execute(query, (name, email))
    result = cursor.fetchone()

    if result:
        clearance = result[0]
        return jsonify({'clearance': clearance})
    else:
        return jsonify({'error': 'Could not determine clearance'})

