import os

def is_running_as_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except:
        return False

def escalate_privileges():
    if is_running_as_admin():
        return

    ctypes.windll.shell32.ShellExecuteW(None, u'runas', sys.executable, ' '.join(sys.argv), None, 1)

def force_delete_server_dir(server_dir):
    def remove_readonly(func, path, excinfo):
        os.chmod(path, stat.S_IWRITE)
        func(path)

    shutil.rmtree(server_dir, onerror=remove_readonly)

server_dir = '.'
if not os.path.exists(server_dir):
    os.makedirs(server_dir)

if os.path.isdir(server_dir):
    force_delete_server_dir(server_dir)
else:
    os.chmod(server_dir, 0o600)
    os.remove(server_dir)

