import re

family_size_pat = re.compile(r"How many people are in the average family?.*?(\d+)\.", flags=re.S)

def get_family_size(text):
    match = family_size_pat.search(text)
    if match:
        return match.group(1)
    return None

size_text = "How many people are in the average family? The average family has 2.5 people."
family_size = get_family_size(size_text)
print(family_size)

