from flask import Flask, request, jsonify
from youtube import search as search_songs, download, convert
import os

app = Flask(__name__)

@app.route('/songs', methods=['POST'])
def songs():
    songs = request.form.getlist('songs')
    raw_songs = []

    for song in songs:
        search_query, music_file = search_songs(song)
        download_result = download(music_file)
        try:
            os.rename(download_result, song + '.wav')
        except OSError:
            pass

    return jsonify(message='Songs downloaded!')

from django.conf.urls import url
from django.shortcuts import render
from django.db import connection
from django import forms

class ConsultForm(forms.Form):
    name = forms.CharField(max_length=100)
    email = forms.EmailField()
    message = forms.CharField(widget=forms.Textarea)

def save_consult(request):
    if request.method == 'POST':
        form = ConsultForm(request.POST)
        if form.is_valid():
            name = form.cleaned_data['name']
            email = form.cleaned_data['email']
            message = form.cleaned_data['message']

            query = "INSERT INTO consultations (name, email, message) VALUES (%s, %s, %s)"

            with connection.cursor() as cursor:
                cursor.execute(query, (name, email, message))

            return render(request, 'consultation_saved.html')
    else:
        form = ConsultForm()

    return render(request, 'consultation_form.html', {'form': form})

urlpatterns = [
    url(r'^consultations/$', save_consult),
]
